<script setup lang="ts">
import {computed,onMounted,ref} from 'vue'
import {ElMessage,ElMessageBox} from 'element-plus'
import {service} from '@/services/service'
import {tools,toolMap} from '@/domain/tools'
import type {Prompt,ToolId} from '@/domain/types'
import {cloneDraft} from '@/domain/validation'
import {newPersonalPrompt,validPromptStage,feeOptions} from '@/domain/prompts'
const prompts=ref<Prompt[]>([]),tool=ref<ToolId|''>(''),scope=ref(''),search=ref(''),loading=ref(false),error=ref(''),current=ref<Prompt|null>(null),editing=ref(false),readOnly=ref(false),saving=ref(false)
const visible=computed(()=>prompts.value.filter(p=>(!tool.value||p.tool===tool.value)&&(!scope.value||p.scope===scope.value)&&(!search.value||p.name.includes(search.value.trim()))))
async function load(){loading.value=true;try{prompts.value=await service.listPrompts();error.value=''}catch(e){error.value=(e as Error).message}finally{loading.value=false}}
function open(p?:Prompt,copy=false){current.value=p?cloneDraft(p):newPersonalPrompt(tool.value||'theme');if(copy){current.value.id='';current.value.name+=' · 个人';current.value.scope='personal'}readOnly.value=!!p&&p.scope!=='personal'&&!copy;editing.value=true}
async function save(){if(!current.value?.name.trim()||!current.value.content.trim()){ElMessage.warning('请填写提示词名称和正文');return}if(!validPromptStage(current.value)){ElMessage.warning('请选择适用工具及分析阶段');return}saving.value=true;try{await service.savePrompt(current.value);editing.value=false;await load()}catch(e){ElMessage.error((e as Error).message)}finally{saving.value=false}}
async function remove(p:Prompt){try{await ElMessageBox.confirm(`删除个人提示词「${p.name}」？历史任务的执行内容仍然保留。`,'删除提示词',{confirmButtonText:'删除',cancelButtonText:'取消'});await service.deletePrompt(p.id);await load()}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error((e as Error).message)}}
onMounted(load)
</script>
<template><div class="prompt-library"><header class="page-heading"><h1>提示词库</h1><el-button type="primary" @click="open()" :disabled="!service.capabilities.personalPrompts">新增个人提示词</el-button></header><section class="panel prompt-list" v-loading="loading"><div class="toolbar"><el-input v-model="search" placeholder="查找提示词" clearable style="width:280px"/><el-select v-model="tool" clearable placeholder="全部工具" style="width:190px"><el-option v-for="t in tools.filter(t=>t.promptStages.length)" :key="t.id" :label="t.name" :value="t.id"/></el-select><el-select v-model="scope" clearable placeholder="全部来源" style="width:170px"><el-option label="公共提示词" value="public"/><el-option label="机构提示词" value="organization"/><el-option label="个人提示词" value="personal"/></el-select></div><el-alert v-if="error" :title="error" type="error" :closable="false"/><el-button v-if="error" @click="load">重试</el-button><el-table :data="visible"><el-table-column prop="name" label="提示词名称" min-width="260"/><el-table-column label="适用工具" width="180"><template #default="{row}">{{row.tool?toolMap[row.tool as ToolId]?.name:'通用'}}</template></el-table-column><el-table-column label="来源" width="190"><template #default="{row}">{{row.scope==='public'?'公共 / '+({system:'系统',function:'功能',scenario:'场景'}[row.category as 'system']||'其他'):row.scope==='organization'?'机构':'个人'}}</template></el-table-column><el-table-column label="操作" min-width="260"><template #default="{row}"><div class="actions"><el-button link type="primary" @click="open(row)">{{row.scope==='personal'?'编辑':'查看'}}</el-button><el-button link type="primary" @click="open(row,true)">另存个人提示词</el-button><el-button v-if="row.scope==='personal'" link type="danger" @click="remove(row)">删除</el-button></div></template></el-table-column></el-table></section><el-dialog v-model="editing" :title="readOnly?'查看提示词':'编辑个人提示词'" width="1120px" :close-on-click-modal="false"><template v-if="current"><div class="prompt-meta"><el-input v-model="current.name" placeholder="提示词名称" :readonly="readOnly" aria-label="提示词名称"/><el-select v-model="current.tool" :disabled="readOnly||!!current.id" @change="current.stage=toolMap[current.tool!].promptStages[0]?.key||'main';current.config={}"><el-option v-for="t in tools.filter(t=>t.promptStages.length)" :key="t.id" :value="t.id" :label="t.name"/></el-select><el-select v-model="current.stage" :disabled="readOnly||!!current.id"><el-option v-if="current.tool==='bidding'&&current.stage==='shared'" label="多阶段共用" value="shared"/><el-option v-for="s in toolMap[current.tool||'theme'].promptStages" :key="s.key" :value="s.key" :label="s.label"/></el-select></div><div v-if="current.tool==='prepaid'" class="prompt-expense"><label>费用类型</label><el-select :model-value="current.config?.expense_type||''" :disabled="readOnly" @change="current.config={...current.config,expense_type:$event}"><el-option label="通用计费提示词" value=""/><el-option v-for="f in feeOptions" :key="f.value" :label="f.label" :value="f.value"/></el-select></div><el-input v-model="current.content" type="textarea" resize="none" class="prompt-body" :readonly="readOnly" aria-label="提示词正文"/></template><template #footer><el-button @click="editing=false">{{readOnly?'关闭':'取消'}}</el-button><el-button v-if="!readOnly" type="primary" :loading="saving" @click="save">保存个人提示词</el-button></template></el-dialog></div></template>
<style scoped>.prompt-expense{display:flex;align-items:center;gap:12px;margin-bottom:12px}.prompt-expense .el-select{width:260px}.prompt-library{height:100%;display:flex;flex-direction:column}.prompt-list{margin:16px;padding:16px;flex:1;min-height:0;overflow:auto}.prompt-list .toolbar{margin-bottom:16px}.prompt-meta{display:grid;grid-template-columns:1fr 200px 200px;gap:12px;margin-bottom:12px}.prompt-body :deep(textarea){height:calc(100dvh - 260px);min-height:220px;font-size:16px;line-height:1.8;padding:16px}@media(max-width:700px){.prompt-meta{grid-template-columns:1fr}.prompt-list{margin:8px;padding:10px}.prompt-body :deep(textarea){height:calc(100dvh - 360px)}}</style>
